import pandas as pd,numpy as np,json,hashlib,platform
ROOT=Path(_release_path('path_53d7a6a979f86dbd'));OUT=ROOT/'q1_depth_n';V6=ROOT.parent/'revision_v6'
def read(p):return pd.read_csv(p,sep='\t')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(d,p):d.to_csv(p,sep='\t',index=False)
def fmt(x):return f'{x:.4g}'

def main():
    verified=json.loads((OUT/'verification_receipt.json').read_text());assert verified['status']=='PASS' and verified['scope']=='all'
