    prim=read(OUT/'N_association_primary.tsv');sens=read(OUT/'N_association_sensitivity.tsv');depth=read(OUT/'depth/counterfactual_summary.tsv');metrics=read(OUT/'models/metrics.tsv');inc=read(OUT/'models/paired_model_increment.tsv');ci=read(OUT/'models/full_pipeline_paired_ci.tsv');le=read(V6/'candidates/Le2017_within_reference_recurrence.tsv');qp=read(V6/'candidates/qpcr_reported_results.tsv');units=read(V6/'candidates/candidate_units.tsv')
